import { useEffect, useId, useRef, useState } from 'react'
import { menu } from '../data/product.js'

// Disclosure navigation (APG): each section button toggles its subsection list.
// Only one section is open at a time; Escape closes it and returns focus.
export default function MainMenu() {
  const [openId, setOpenId] = useState(null)
  const navRef = useRef(null)
  const buttonRefs = useRef({})
  const baseId = useId()

  useEffect(() => {
    if (!openId) return
    function onPointerDown(event) {
      if (!navRef.current.contains(event.target)) setOpenId(null)
    }
    document.addEventListener('pointerdown', onPointerDown)
    return () => document.removeEventListener('pointerdown', onPointerDown)
  }, [openId])

  function close(id) {
    setOpenId(null)
    buttonRefs.current[id]?.focus()
  }

  return (
    <nav aria-label="Main" className="main-menu" ref={navRef}>
      <ul className="menu-list">
        {menu.map((section) => {
          if (!section.subsections) {
            return (
              <li key={section.id}>
                <a className="menu-link" href={section.href}>
                  {section.label}
                </a>
              </li>
            )
          }
          const expanded = openId === section.id
          const panelId = `${baseId}-${section.id}`
          return (
            <li
              key={section.id}
              className="menu-item"
              onKeyDown={(event) => {
                if (event.key === 'Escape' && expanded) close(section.id)
              }}
            >
              <button
                type="button"
                className="menu-button"
                aria-expanded={expanded}
                aria-controls={expanded ? panelId : undefined}
                ref={(node) => {
                  buttonRefs.current[section.id] = node
                }}
                onClick={() => setOpenId(expanded ? null : section.id)}
              >
                {section.label}
                <span aria-hidden="true" className="chevron">
                  {expanded ? '▴' : '▾'}
                </span>
              </button>
              {expanded && (
                <div className="menu-panel" id={panelId}>
                  <ul>
                    {section.subsections.map((link) => (
                      <li key={link.label}>
                        <a href={link.href}>{link.label}</a>
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </li>
          )
        })}
      </ul>
    </nav>
  )
}
