import { useId, useState } from 'react'
import { catalog } from '../data/product.js'

// Search with suggestions. The input keeps the searchbox role and points at
// the suggestion list through aria-activedescendant (keyboard: arrows, Enter, Escape).
export default function SearchBox() {
  const baseId = useId()
  const inputId = `${baseId}-input`
  const listId = `${baseId}-suggestions`
  const [query, setQuery] = useState('')
  const [activeIndex, setActiveIndex] = useState(-1)
  const [dismissed, setDismissed] = useState(false)

  const term = query.trim().toLowerCase()
  const results = term ? catalog.filter((item) => item.name.toLowerCase().includes(term)).slice(0, 6) : []
  const open = results.length > 0 && !dismissed
  const activeId = open && activeIndex >= 0 ? `${baseId}-option-${activeIndex}` : undefined

  function openProduct(item) {
    window.location.assign(`/products/${item.slug}`)
  }

  function onKeyDown(event) {
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      if (results.length === 0) return
      event.preventDefault()
      const down = event.key === 'ArrowDown'
      const count = results.length
      setDismissed(false)
      setActiveIndex((i) => {
        if (down) return i < 0 ? 0 : (i + 1) % count
        return i <= 0 ? count - 1 : i - 1
      })
    } else if (event.key === 'Enter' && open && activeIndex >= 0) {
      event.preventDefault()
      openProduct(results[activeIndex])
    } else if (event.key === 'Escape' && open) {
      event.preventDefault()
      setDismissed(true)
      setActiveIndex(-1)
    }
  }

  function onSubmit(event) {
    event.preventDefault()
    const text = query.trim()
    if (text) window.location.assign(`/search?q=${encodeURIComponent(text)}`)
  }

  return (
    <form
      role="search"
      className="search"
      onSubmit={onSubmit}
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) setDismissed(true)
      }}
    >
      <label className="visually-hidden" htmlFor={inputId}>
        Search products
      </label>
      <input
        id={inputId}
        type="search"
        className="search-input"
        autoComplete="off"
        value={query}
        aria-autocomplete="list"
        aria-controls={open ? listId : undefined}
        aria-activedescendant={activeId}
        onChange={(event) => {
          setQuery(event.target.value)
          setActiveIndex(-1)
          setDismissed(false)
        }}
        onFocus={() => setDismissed(false)}
        onKeyDown={onKeyDown}
      />
      <button type="submit" className="search-button">
        Search
      </button>
      <p className="visually-hidden" aria-live="polite">
        {open ? `${results.length} suggestions available` : ''}
      </p>
      {open && (
        <ul id={listId} role="listbox" aria-label="Suggestions" className="suggestions">
          {results.map((item, index) => (
            <li
              key={item.slug}
              id={`${baseId}-option-${index}`}
              role="option"
              aria-selected={index === activeIndex}
              className={index === activeIndex ? 'suggestion is-active' : 'suggestion'}
              onMouseDown={(event) => event.preventDefault()}
              onClick={() => openProduct(item)}
            >
              {item.name}
            </li>
          ))}
        </ul>
      )}
    </form>
  )
}
