import { useEffect, useState } from 'react'
import { colors as allColors, photoViews, product } from '../data/product.js'
import { shoeImage } from '../lib/shoeArt.js'

const INTERVAL_MS = 5000

// Auto-advancing photo carousel. Auto-rotation can be paused (WCAG 2.2.2),
// and the live region is only polite while the slides are not moving.
export default function PhotoGallery({ colorId, colorLabel }) {
  const [index, setIndex] = useState(0)
  const [playing, setPlaying] = useState(true)
  const count = photoViews.length
  const view = photoViews[index]

  useEffect(() => {
    if (!playing) return undefined
    const timer = setInterval(() => setIndex((i) => (i + 1) % count), INTERVAL_MS)
    return () => clearInterval(timer)
  }, [playing, count])

  return (
    <section className="gallery" aria-label="Product photos">
      <div className="stage" aria-live={playing ? 'off' : 'polite'}>
        <img
          className="gallery-image"
          src={shoeImage(colorId, allColors, view.id)}
          alt={`${product.name} in ${colorLabel.toLowerCase()}, ${view.label}`}
          width="600"
          height="450"
        />
      </div>
      <div className="gallery-controls">
        <button type="button" onClick={() => setIndex((i) => (i - 1 + count) % count)}>
          Previous
        </button>
        <button type="button" aria-pressed={!playing} onClick={() => setPlaying((p) => !p)}>
          {playing ? 'Pause' : 'Play'}
        </button>
        <button type="button" onClick={() => setIndex((i) => (i + 1) % count)}>
          Next
        </button>
        <span className="photo-count">
          Photo {index + 1} of {count}
        </span>
      </div>
    </section>
  )
}
