import { useEffect, useId, useRef, useState } from 'react'
import { sizes, soldOutSizes } from '../data/product.js'
import { formatSize, usSize } from '../lib/format.js'

// Size picker (APG select-only listbox): the list opens only on request, and
// sold-out sizes are shown but cannot be chosen.
export default function SizePicker({ value, onChange, onOpenGuide, buttonRef }) {
  const baseId = useId()
  const wrapRef = useRef(null)
  const listRef = useRef(null)
  const [open, setOpen] = useState(false)
  const [activeIndex, setActiveIndex] = useState(0)
  const listId = `${baseId}-list`

  function openList() {
    const current = sizes.indexOf(value)
    setActiveIndex(current >= 0 ? current : sizes.findIndex((s) => !soldOutSizes.includes(s)))
    setOpen(true)
  }

  function closeList() {
    setOpen(false)
    buttonRef.current?.focus()
  }

  useEffect(() => {
    if (open) listRef.current?.focus()
  }, [open])

  function choose(index) {
    const size = sizes[index]
    if (soldOutSizes.includes(size)) return
    onChange(size)
    closeList()
  }

  function onKeyDown(event) {
    const last = sizes.length - 1
    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault()
        setActiveIndex((i) => Math.min(i + 1, last))
        break
      case 'ArrowUp':
        event.preventDefault()
        setActiveIndex((i) => Math.max(i - 1, 0))
        break
      case 'Home':
        event.preventDefault()
        setActiveIndex(0)
        break
      case 'End':
        event.preventDefault()
        setActiveIndex(last)
        break
      case 'Enter':
      case ' ':
        event.preventDefault()
        choose(activeIndex)
        break
      case 'Escape':
        event.preventDefault()
        closeList()
        break
      default:
        break
    }
  }

  return (
    <div
      className="size-picker"
      ref={wrapRef}
      onBlur={(event) => {
        if (open && !wrapRef.current.contains(event.relatedTarget)) setOpen(false)
      }}
    >
      <div className="size-row">
        <button
          type="button"
          ref={buttonRef}
          className="size-button"
          aria-haspopup="listbox"
          aria-expanded={open}
          aria-controls={open ? listId : undefined}
          onClick={() => (open ? closeList() : openList())}
        >
          <span className="field-label">Size</span>{' '}
          <span className="field-value">{value ? usSize(value) : 'Select a size'}</span>
        </button>
        <button type="button" className="link-button" onClick={onOpenGuide}>
          Size guide
        </button>
      </div>
      {open && (
        <ul
          id={listId}
          ref={listRef}
          role="listbox"
          aria-label="Size"
          tabIndex={-1}
          className="size-list"
          aria-activedescendant={`${baseId}-size-${activeIndex}`}
          onKeyDown={onKeyDown}
        >
          {sizes.map((size, index) => {
            const soldOut = soldOutSizes.includes(size)
            return (
              <li
                key={size}
                id={`${baseId}-size-${index}`}
                role="option"
                aria-selected={size === value}
                aria-disabled={soldOut || undefined}
                className={[
                  'size-option',
                  index === activeIndex ? 'is-active' : '',
                  soldOut ? 'is-sold-out' : '',
                ].join(' ')}
                onMouseDown={(event) => event.preventDefault()}
                onMouseEnter={() => setActiveIndex(index)}
                onClick={() => choose(index)}
              >
                {usSize(size)}
                {soldOut && <span className="sold-out-tag"> Sold out</span>}
              </li>
            )
          })}
        </ul>
      )}
      <span className="visually-hidden">{formatSize(value ?? 0) === '0' ? '' : ''}</span>
    </div>
  )
}
