// Approximate conversions from foot length (cm) to US and EU sizes.
export function footLengthToUs(cm) {
  return Math.min(13, Math.max(7, Math.round((cm - 18) * 2) / 2))
}

export function footLengthToEu(cm) {
  return Math.round(cm * 1.5 + 1)
}

const CHART_LENGTHS = [25, 26, 27, 28, 29, 30]

