import { useId, useState } from 'react'
import { soldOutSizes, sizes, stores } from '../data/product.js'
import { formatSize, usSize } from '../lib/format.js'

export function isInStock(store, size) {
  return !soldOutSizes.includes(size) && !store.soldOut.includes(size)
}

// Stores as rows and sizes as columns (APG grid with roving focus).
// Choosing a cell sets both the store and the size.
export default function StoreAvailability({ size, pickupStoreId, onPick }) {
  const headingId = useId()
  const firstEnabled = findNextEnabled(0, 0, 0, 1)
  const [tabStop, setTabStop] = useState(() => firstEnabled ?? { r: 0, c: 0 })
  const pickupStore = stores.find((s) => s.id === pickupStoreId)

  function findNextEnabled(r, c, dr, dc) {
    let row = r
    let col = c
    for (let i = 0; i < stores.length * sizes.length; i++) {
      row += dr
      col += dc
      if (row < 0 || row >= stores.length) return null
      if (col < 0 || col >= sizes.length) {
        if (dc !== 0) return null
        col = (col + sizes.length) % sizes.length
      }
      if (isInStock(stores[row], sizes[col])) return { r: row, c: col }
    }
    return null
  }

  function focusCell(cell) {
    setTabStop(cell)
    document.querySelector(`[data-grid="stock"] [data-r="${cell.r}"][data-c="${cell.c}"]`)?.focus()
  }

  function onKeyDown(event) {
    const moves = {
      ArrowLeft: [0, -1],
      ArrowRight: [0, 1],
      ArrowUp: [-1, 0],
      ArrowDown: [1, 0],
    }
    const move = moves[event.key]
    if (!move) return
    event.preventDefault()
    // Search step by step in the arrow direction, skipping sold-out cells.
    const [dr, dc] = move
    let row = tabStop.r
    let col = tabStop.c
    for (;;) {
      row += dr
      col += dc
      if (row < 0 || row >= stores.length || col < 0 || col >= sizes.length) return
      if (isInStock(stores[row], sizes[col])) {
        focusCell({ r: row, c: col })
        return
      }
    }
  }

  return (
    <section className="stores" aria-labelledby={headingId}>
      <h2 id={headingId} className="section-title">
        Store availability
      </h2>
      <p className="hint">
        Stock at nearby stores. ● in stock, × sold out. Choose an in-stock cell to choose a store and size.
      </p>
      <div className="grid-scroll" data-grid="stock">
        <table role="grid" aria-labelledby={headingId} className="stock-grid" onKeyDown={onKeyDown}>
          <thead>
            <tr>
              <th scope="col">Store</th>
              {sizes.map((s) => (
                <th scope="col" key={s}>
                  {formatSize(s)}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {stores.map((store, r) => (
              <tr key={store.id}>
                <th scope="row">
                  {store.name}
                  <span className="store-city">{store.city}</span>
                </th>
                {sizes.map((s, c) => {
                  const inStock = isInStock(store, s)
                  const selected = store.id === pickupStoreId && s === size
                  const isTab = tabStop.r === r && tabStop.c === c
                  return (
                    <td role="gridcell" key={s}>
                      <button
                        type="button"
                        data-r={r}
                        data-c={c}
                        disabled={!inStock}
                        tabIndex={isTab ? 0 : -1}
                        aria-pressed={selected}
                        aria-label={`${store.name}, ${usSize(s)}, ${inStock ? 'in stock' : 'sold out'}`}
                        className={selected ? 'stock-cell is-selected' : 'stock-cell'}
                        onFocus={() => setTabStop({ r, c })}
                        onClick={() => onPick(store.id, s)}
                      >
                        <span aria-hidden="true">{inStock ? '●' : '×'}</span>
                      </button>
                    </td>
                  )
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {pickupStore && size != null && (
        <p className="pickup-note">
          {isInStock(pickupStore, size)
            ? `Pick up at ${pickupStore.name} in ${usSize(size)}.`
            : `${usSize(size)} is sold out at ${pickupStore.name}. Choose another size or store.`}
        </p>
      )}
    </section>
  )
}
