import { useEffect, useId, useRef, useState } from 'react'
import { addDays, addMonths, dateKey, sameDay, startOfDay, startOfMonth } from '../lib/format.js'

const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
const WEEKDAY_NAMES = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
const WINDOW_DAYS = 30

// Delivery is possible from tomorrow for the next 30 days, Sundays excluded.
function isAvailable(date) {
  const today = startOfDay(new Date())
  return date >= addDays(today, 1) && date <= addDays(today, WINDOW_DAYS) && date.getDay() !== 0
}

// Walks from `start` in direction `step` until an available day is found.
function seek(start, step) {
  let date = start
  for (let i = 0; i < 80; i++) {
    if (isAvailable(date)) return date
    date = addDays(date, step)
  }
  return null
}

function longDate(date) {
  return date.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' })
}

function monthTitle(date) {
  return date.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })
}

function buildWeeks(month) {
  const first = startOfMonth(month)
  const daysInMonth = new Date(first.getFullYear(), first.getMonth() + 1, 0).getDate()
  const cells = []
  for (let i = 0; i < first.getDay(); i++) cells.push(null)
  for (let d = 1; d <= daysInMonth; d++) cells.push(new Date(first.getFullYear(), first.getMonth(), d))
  while (cells.length % 7 !== 0) cells.push(null)
  const weeks = []
  for (let i = 0; i < cells.length; i += 7) weeks.push(cells.slice(i, i + 7))
  return weeks
}

// Delivery date picker: a button opens a calendar grid (APG date picker).
// Arrow keys move between days (skipping unavailable ones), PageUp/PageDown
// change month, Home/End go to the ends of the week, Escape closes.
export default function DeliveryDate({ value, onChange }) {
  const baseId = useId()
  const panelId = `${baseId}-calendar`
  const toggleRef = useRef(null)
  const gridRef = useRef(null)
  const pendingFocus = useRef(false)
  const [open, setOpen] = useState(false)
  const [focusDate, setFocusDate] = useState(() => value ?? seek(addDays(startOfDay(new Date()), 1), 1))
  const [viewMonth, setViewMonth] = useState(() => startOfMonth(focusDate))

  useEffect(() => {
    if (open && pendingFocus.current) {
      gridRef.current?.querySelector(`[data-date="${dateKey(focusDate)}"]`)?.focus()
      pendingFocus.current = false
    }
  }, [open, focusDate, viewMonth])

  const weeks = buildWeeks(viewMonth)
  const focusInView = focusDate.getMonth() === viewMonth.getMonth() && focusDate.getFullYear() === viewMonth.getFullYear()
  const firstAvailableInView = weeks.flat().find((d) => d && isAvailable(d))

  function moveFocus(date) {
    setFocusDate(date)
    setViewMonth(startOfMonth(date))
    pendingFocus.current = true
  }

  function pick(date) {
    onChange(date)
    setFocusDate(date)
    setOpen(false)
    toggleRef.current?.focus()
  }

  function onGridKeyDown(event) {
    const moves = {
      ArrowLeft: () => seek(addDays(focusDate, -1), -1),
      ArrowRight: () => seek(addDays(focusDate, 1), 1),
      ArrowUp: () => seek(addDays(focusDate, -7), -1),
      ArrowDown: () => seek(addDays(focusDate, 7), 1),
      PageUp: () => seek(addMonths(focusDate, -1), 1),
      PageDown: () => seek(addMonths(focusDate, 1), 1),
      Home: () => seek(addDays(focusDate, -focusDate.getDay()), 1),
      End: () => seek(addDays(focusDate, 6 - focusDate.getDay()), -1),
    }
    const move = moves[event.key]
    if (!move) return
    event.preventDefault()
    const next = move()
    if (next) moveFocus(next)
  }

  function onPanelKeyDown(event) {
    if (event.key === 'Escape') {
      event.preventDefault()
      setOpen(false)
      toggleRef.current?.focus()
    }
  }

  return (
    <div className="delivery">
      <button
        type="button"
        ref={toggleRef}
        className="secondary-button"
        aria-expanded={open}
        aria-controls={open ? panelId : undefined}
        onClick={() => {
          if (!open) pendingFocus.current = true
          setOpen((o) => !o)
        }}
      >
        {value ? 'Change delivery date' : 'Choose delivery date'}
      </button>
      {value && <p className="delivery-date">Delivery: {longDate(value)}</p>}

      {open && (
        <div id={panelId} className="calendar" onKeyDown={onPanelKeyDown}>
          <div className="calendar-head">
            <button type="button" onClick={() => setViewMonth((m) => addMonths(m, -1))}>
              Previous month
            </button>
            <span className="calendar-title">{monthTitle(viewMonth)}</span>
            <button type="button" onClick={() => setViewMonth((m) => addMonths(m, 1))}>
              Next month
            </button>
          </div>
          <table
            role="grid"
            ref={gridRef}
            className="calendar-grid"
            aria-label={`${monthTitle(viewMonth)}, delivery calendar`}
            onKeyDown={onGridKeyDown}
          >
            <thead>
              <tr>
                {WEEKDAYS.map((day, i) => (
                  <th key={day} scope="col" abbr={WEEKDAY_NAMES[i]}>
                    {day}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {weeks.map((week, wi) => (
                <tr key={wi}>
                  {week.map((date, di) => {
                    if (!date) return <td role="gridcell" key={di} />
                    const available = isAvailable(date)
                    const isTabStop = sameDay(date, focusDate) || (!focusInView && date === firstAvailableInView)
                    return (
                      <td role="gridcell" key={di} aria-selected={Boolean(value && sameDay(date, startOfDay(value)))}>
                        <button
                          type="button"
                          data-date={dateKey(date)}
                          disabled={!available}
                          tabIndex={isTabStop ? 0 : -1}
                          aria-label={`${WEEKDAY_NAMES[date.getDay()]}, ${longDate(date).split(', ').slice(1).join(', ')}`}
                          onFocus={() => setFocusDate(date)}
                          onClick={() => pick(date)}
                        >
                          {date.getDate()}
                        </button>
                      </td>
                    )
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  )
}
