import { details, reviews, shipping, product } from '../data/product.js'

const TABS = [
  { id: 'details', label: 'Details' },
  { id: 'reviews', label: 'Reviews' },
  { id: 'shipping', label: 'Shipping' },
]

// Details, reviews and shipping as one-at-a-time tabs (APG tabs pattern).
export default function MoreInformation() {
  const baseId = useId()
  const [selected, setSelected] = useState('details')
  const tabRefs = useRef({})

  function select(id, focus = false) {
    setSelected(id)
    if (focus) tabRefs.current[id]?.focus()
  }

  function onKeyDown(event, index) {
    let next = null
    if (event.key === 'ArrowRight') next = (index + 1) % TABS.length
    if (event.key === 'ArrowLeft') next = (index - 1 + TABS.length) % TABS.length
    if (event.key === 'Home') next = 0
    if (event.key === 'End') next = TABS.length - 1
    if (next === null) return
    event.preventDefault()
    select(TABS[next].id, true)
  }

  return (
    <section className="more-info" aria-labelledby={`${baseId}-heading`}>
      <h2 id={`${baseId}-heading`} className="section-title">
