  const [colorId, setColorId] = useState('blue')
  const [size, setSize] = useState(null)
  const [pickupStoreId, setPickupStoreId] = useState(null)
  const [quantity, setQuantity] = useState(1)
  const [deliveryDate, setDeliveryDate] = useState(null)
  const [cartCount, setCartCount] = useState(0)
  const [wishlisted, setWishlisted] = useState(false)
  const [sizeError, setSizeError] = useState('')
  const [message, setMessage] = useState('')
  const [guideOpen, setGuideOpen] = useState(false)
  const sizeButtonRef = useRef(null)
  const color = colors.find((c) => c.id === colorId)

  useEffect(() => {
    document.title = `${product.name} | Stride`
  }, [])

  function chooseSize(next) {
    setSize(next)
    setSizeError('')
  }

  function pickInStore(storeId, nextSize) {
    setPickupStoreId(storeId)
    chooseSize(nextSize)
  }

  function addToCart() {
    if (size == null) {
      setSizeError('Choose a size before adding this shoe to your cart.')
      sizeButtonRef.current?.focus()
      return
    }
    setSizeError('')
    setCartCount((n) => n + quantity)
    setMessage(`Added to your cart: ${quantity} × ${product.name}, ${usSize(size)}, ${color.label}.`)
  }

  function toggleWishlist() {
    setWishlisted((saved) => {
      setMessage(saved ? `${product.name} removed from your wishlist.` : `${product.name} saved to your wishlist.`)
      return !saved
    })
  }

  return (
    <>
      <a className="skip-link" href="#main">
        Skip to main content
      </a>

      {/* Everything behind the size guide is inert while it is open. */}
      <div inert={guideOpen}>
        <SiteHeader cartCount={cartCount} />

        <main id="main" className="page">
          <Breadcrumb />

          <div className="product-layout">
            <PhotoGallery colorId={colorId} colorLabel={color.label} />

            <div className="buy-box">
              <h1>{product.name}</h1>
              <p className="rating">
                Rated {product.rating} out of 5 · {product.reviewCount} reviews
              </p>
              <PriceInfo amount={product.price} />

              <ColorChooser value={colorId} onChange={setColorId} />

              <SizePicker
                value={size}
                onChange={chooseSize}
                onOpenGuide={() => setGuideOpen(true)}
                buttonRef={sizeButtonRef}
              />
              {sizeError && (
                <p className="field-error" role="alert">
                  {sizeError}
                </p>
              )}

              <StoreAvailability size={size} pickupStoreId={pickupStoreId} onPick={pickInStore} />

              <QuantityInput value={quantity} onChange={setQuantity} />

              <DeliveryDate value={deliveryDate} onChange={setDeliveryDate} />

              <div className="actions">
                <button type="button" className="primary-button add-to-cart" onClick={addToCart}>
                  Add to cart
                </button>
                <button
                  type="button"
                  className="wishlist-button"
                  aria-pressed={wishlisted}
                  onClick={toggleWishlist}
                >
                  <span aria-hidden="true">{wishlisted ? '♥' : '♡'}</span> Save to wishlist
                </button>
              </div>

              <p role="status" className="status">
                {message}
              </p>
            </div>
          </div>

          <MoreInformation />
          <FaqList />
        </main>

        <SiteFooter />
      </div>

      {guideOpen && <SizeGuide onClose={() => setGuideOpen(false)} onUseSize={(s) => { chooseSize(s); setGuideOpen(false) }} />}
    </>
  )
}
