.faq-item h3 {
  font-size: 1rem;
}

.faq-question {
  width: 100%;
  min-height: 48px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 12px 4px;
  font: inherit;
  font-weight: 600;
  text-align: left;
  color: var(--ink);
  background: none;
  border: 0;
  cursor: pointer;
}

.faq-answer {
  padding: 0 4px 16px;
}

.faq-answer[hidden] {
  display: none;
}

.chevron {
  font-size: 1.2rem;
  flex: none;
}

/* ---------- Footer ---------- */

.site-footer {
  background: #e7e9ed;
  margin-top: 32px;
  padding: 32px 16px 20px;
}

.footer-grid {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 24px;
}

.footer-group h2 {
  font-size: 1rem;
  margin-bottom: 8px;
}

.footer-group ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

.footer-group a {
  display: inline-flex;
  align-items: center;
  min-height: 32px;
  color: var(--ink);
}

.copyright {
  max-width: 1200px;
  margin: 24px auto 0;
  color: var(--muted);
  font-size: 0.9rem;
}
